C.append(make('tree_human_creator','人树结合研究者','这名未具名的外星研究者曾在地球进行人类与树木生命的结合实验，选择两对相爱的男女作为人的生命来源，把相应因素放入树木中孕育。米寄生与其情侣是能够活动的成果，另一对因大树提前被砍而木质化，研究者后来与黄蝉和勒曼医院协作，试图调整他们的生命形式。他口中的还阳指增强人的因素，不是把死者从阴间召回，误解这一术语会夸大其能力。'+'他起初对卫斯理态度不耐，又通过米博士与电话安排推动合作，造成隐瞒和被利用的感受。治疗需要大亨与朱槿的特定脑内分泌、长期医疗设备和自愿配合，并非任何材料都可替代。他与黄蝉约定，木人恢复后不由她的组织插手；半年后报告顺利，仍有后续生长阶段。卡片保留其研究成就，也保留实验把别人的生命作为研究对象所引发的争议。他不是整个勒曼医院的同义词，不拥有其他研究者全部技术；可以学会更清楚说明风险与尊重实验对象，而不凭先进身份免去解释义务。',
'《遗传》半年后报告治疗顺利；木质男女仍需约一年达到米寄生形态，最终全貌未当场展示。',[skill('人树生命结合与定向治疗','借特定生命材料、遗传条件与长期医疗设施组织实验，调整人树生命中不同部分的表现。','通讯、资料、实验体和长期医疗过程；不以瞬间施法展现。',['研究复合生命','寻找与实验对象匹配的后裔','协作治疗木质化'],'需要特定材料、志愿者和设备，曾发生意外；不能任意创造生命、即时复活或把医院全部成果算作个人战斗技能。')],
'完成并维护自己创造的生命形式，解决实验中留下的危机。',['研究结果须面对实际意外','必要合作不能用简单强迫代替','独立对象恢复后有自己的生活'],tr,
[ev(108,1528,1553,'与还阳的同一研究者'),ev(108,2333,2347,'四名实验生命'),ev(108,2397,2423,'实验条件'),ev(108,2652,2676,'治疗紧迫性与还阳定义'),ev(108,2694,2705,'网络笔记本与隐私'),ev(108,2719,2737,'治疗进度和自愿')],(1,1,3,4,3,2),['个体身体不明从低','医疗技术非自身能量炮','多名实验对象','需长期医疗资源','通讯与设备作用范围','实验经验不等于战斗专长'],roles=['重要配角','伦理争议行动者'],negative=(1,3,1),body={'durability':'本体形态未充分展现，不补入任何物理或元素免疫。','speed':'主要经通讯与协作行动，未展示本体超速或瞬移。'},uncertain=['没有充分证据把曲先生认作独立真实人物或其固定姓名。']))
