 tr=[('自身恢复依赖别人提供材料','他人可以自主选择','保留对治疗的需要，不把索取写成天然权利。'),('有人以出身决定自己的命运','尚无独立行动可证','演绎只采用明确声明的开放性改编，不替原作定下野心或恋情结局。'),('能开始与人沟通','须明确以恢复后的部署为前提','从当下的感受与选择建立关系，避免一开始就全知自己的历史。')]
 bio='这位木质'+sex+'性是外星人树结合实验中的一名生命，与另一位同类从被砍的大树中出现，成为《还阳》到《遗传》持续追索的对象。外表具有人形，生命形式却因孕育中断而偏向树木，不能按普通人体活动。'+desc+'不过遗传来源不等于同一个历史人物重生，也不能让其继承古帝后的全部记忆、军队或政治责任。'+'研究者希望取得'+counter+'的特定脑内分泌，增强人的因素，使其逐渐成为米寄生那样可活动的生命。半年后的消息说治疗顺利，还需要一年；小说没有直接展示此人的完整恢复、独立谈话和最终生活。卡片因此把已知生命状态和他人的预测分开：长寿、爱情延续与竞争野心都不能一律当作已经验证的主动能力。若用于互动，需明确约定治疗完成且能交流的改编形态，给其探索自身意愿的空间；这种开放性格是部署需要，不是从几段外貌描写推导出的固定原作人格。角色的价值在于对被创造、被研究与自主生活的选择，而非充当任何后裔的复制品。'
 c=human(key,'木质'+sex+'人（还阳实验）',bio,'《遗传》半年后治疗顺利，尚需一年；完整活动与人格状态未直接展示。','人树结合生命的被治疗状态；没有已证实的自主战斗技能。','在明确恢复部署后探索自身生命与独立选择；原作未给可确证的私人动机。',tr,[ev(108,2333,2383,'木质化与治疗机制'),ev(108,2541,2609,'遗传来源'),ev(108,2719,2735,'未完成的生长阶段')],stats=(0,0,0,1,0,0),roles=['跨书核心对象'])
